/**
 * Post-build step for Freebuff Sites.
 *
 * Vite copies public/gallery/ — the untouched originals — into dist verbatim.
 * The Sites uploader refuses '~' in asset paths, hidden files and bundles over
 * 10 MiB, so this swaps in the web-ready copies from gallery-web/ (generated by
 * scripts/build-gallery-web.py) and fails loudly if the result would not upload.
 */
import fs from "node:fs";
import path from "node:path";

const DIST = "dist";
const GALLERY = path.join(DIST, "gallery");
const WEB = "gallery-web";
const LIMIT = 10 * 1024 * 1024;
const SAFE_NAME = /^[A-Za-z0-9._-]+$/;

function fail(message) {
  console.error(`prepare-gallery: ${message}`);
  process.exit(1);
}

if (!fs.existsSync(WEB)) fail(`missing ${WEB}/ — run: python3 scripts/build-gallery-web.py`);

// 1. Replace the full-resolution originals with their upload-safe copies.
fs.rmSync(GALLERY, { recursive: true, force: true });
fs.mkdirSync(GALLERY, { recursive: true });
const copies = fs.readdirSync(WEB).filter((name) => !name.startsWith("."));
if (copies.length === 0) fail(`${WEB}/ is empty`);
for (const name of copies) {
  fs.copyFileSync(path.join(WEB, name), path.join(GALLERY, name));
}

// 2. Sweep anything the uploader rejects: hidden files and reserved names.
function sweep(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) sweep(full);
    else if (entry.name.startsWith(".") || entry.name === "_redirects" || entry.name === "_headers")
      fs.rmSync(full, { force: true });
  }
}
sweep(DIST);

// 3. Verify what will be uploaded.
let total = 0;
const bad = [];
function measure(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) measure(full);
    else {
      total += fs.statSync(full).size;
      if (!SAFE_NAME.test(entry.name)) bad.push(full);
    }
  }
}
measure(DIST);

if (bad.length) fail(`unsafe asset paths: ${bad.slice(0, 5).join(", ")}`);
if (total > LIMIT) fail(`bundle is ${(total / 1048576).toFixed(2)} MiB, limit is 10 MiB`);

console.log(
  `prepare-gallery: ${copies.length} photographs, ${(total / 1048576).toFixed(2)} MiB total — upload ready`
);
